mapper.select:
SELECT bid_notice_id
FROM bid_notice
WHERE crawl_source_id = #{sourceId}
  AND external_id = #{externalId}
  AND notice_ord = #{noticeOrder}
LIMIT 1

mapper.update:
UPDATE bid_notice
SET crawled_at = #{crawledAt}
WHERE bid_notice_id = #{noticeId}

mapper.insert:
INSERT IGNORE INTO bid_notice_raw (
    bid_notice_id, crawl_run_id, source_code, payload_type,
    raw_payload, raw_payload_hash, parsed_at, created_at
) VALUES (
    #{noticeId}, #{runId}, #{sourceCode}, 'JSON',
    CAST(#{rawPayload} AS JSON), #{rawPayloadHash},
    #{parsedAt}, #{parsedAt}
)
